      'Reviewed Goat Funded Trader official platform FAQ on 2026-10-01. It lists five firm-level platforms and U.S. restrictions for MT5/cTrader, but does not publish the offer-level platform mapping for Instant Pro.')
), updated as (
  update bullish_banana.programs p
  set commercial_details = coalesce(p.commercial_details, '{}'::jsonb) || jsonb_build_object(
    'platform_availability_note', o.disclosure,
    'platform_scope_verified_at', '2026-10-01'
  ), updated_at = now()
  from bullish_banana.firms f, offers o
  where p.firm_id = f.id and f.slug = o.firm_slug and p.slug = o.program_slug
    and p.market_type = 'forex' and p.status in ('published','in_review')
  returning p.id, p.firm_id, p.slug
)
insert into bullish_banana.sources (program_id, source_url, source_label, notes)
select p.id, o.source_url, o.source_title || ' — ' || p.slug, o.disclosure
from updated p
join bullish_banana.firms f on f.id = p.firm_id
join offers o on f.slug = o.firm_slug and p.slug = o.program_slug
where not exists (select 1 from bullish_banana.sources s
  where s.program_id = p.id and s.source_label = o.source_title || ' — ' || p.slug);

