insert into bullish_banana.data_verifications (program_id, verified_at, notes)
select p.id, '2026-10-01T04:00:00+09:00'::timestamptz, o.verification
from offers o
join bullish_banana.firms f on f.slug = o.firm_slug
join bullish_banana.programs p on p.firm_id = f.id and p.slug = o.program_slug
where p.market_type = 'forex' and p.status in ('published','in_review')
  and not exists (select 1 from bullish_banana.data_verifications v
    where v.program_id = p.id and v.notes = o.verification);

commit;
